<script setup>
import { computed, onMounted, ref } from 'vue'
const authenticated=ref(false),password=ref(''),error=ref(''),orders=ref([]),analytics=ref(null),forgotPassword=ref(false),otp=ref(''),newPassword=ref(''),otpNote=ref(''),otpSending=ref(false)
const request=async(path,options={})=>{const response=await fetch(path,{credentials:'same-origin',headers:{'Content-Type':'application/json'},...options}),data=response.status===204?null:await response.json();if(!response.ok)throw new Error(data.error||'Something went wrong.');return data}
const load=async()=>{orders.value=(await request('/api/admin/orders')).orders;analytics.value=await request('/api/admin/analytics')}
const login=async()=>{error.value='';try{await request('/api/admin/login',{method:'POST',body:JSON.stringify({password:password.value})});authenticated.value=true;await load()}catch(e){error.value=e.message}}
const logout=async()=>{await request('/api/admin/logout',{method:'POST'});authenticated.value=false}
const changeStatus=async(order,status)=>{await request(`/api/admin/orders/${order.id}`,{method:'PATCH',body:JSON.stringify({status})});await load()}
const closeTicket=async ticket=>{await request(`/api/admin/tickets/${ticket.id}`,{method:'PATCH',body:JSON.stringify({status:'resolved'})});await load()}
const sendOtp=async()=>{if(otpSending.value)return;otpSending.value=true;otpNote='Sending OTP…';try{const data=await request('/api/admin/password/otp',{method:'POST'});otpNote=`A six-digit OTP was sent to ${data.sentTo}.`}catch(e){otpNote=`OTP was not sent: ${e.message}`}finally{otpSending.value=false}}
const changePassword=async()=>{try{await request('/api/admin/password',{method:'POST',body:JSON.stringify({otp:otp.value,password:newPassword.value})});otpNote='Password changed. You can now sign in.';password.value='';otp.value='';newPassword.value='';forgotPassword.value=false}catch(e){otpNote=e.message}}
const currentStatus=order=>order.status==='complete'?'complete':'pending'
const openTickets=computed(()=>orders.value.flatMap(order=>order.tickets).filter(ticket=>ticket.status==='open').length)
onMounted(async()=>{try{await load();authenticated.value=true}catch{}})
</script>
<template><section class="page admin-page"><div v-if="!authenticated" class="wrap admin-login"><p class="eyebrow">RAWR admin</p><h1>{{forgotPassword?'Reset admin password.':'Sign in to manage orders.'}}</h1><template v-if="!forgotPassword"><form @submit.prevent="login"><label>Admin password<input v-model="password" type="password" autocomplete="current-password" required></label><p v-if="error" class="error">{{error}}</p><button class="button primary">Sign in</button></form><button class="switch" @click="forgotPassword=true;otpNote=''">Forgot password?</button></template><template v-else><p class="reset-copy">We’ll email a six-digit verification code to rawr.bizmind@gmail.com.</p><button class="button dark" @click="sendOtp">Send OTP</button><form @submit.prevent="changePassword"><label>6-digit OTP<input v-model="otp" inputmode="numeric" maxlength="6" required></label><label>New password<input v-model="newPassword" type="password" minlength="10" required></label><button class="button primary">Update password</button></form><p v-if="otpNote" class="note">{{otpNote}}</p><button class="switch" @click="forgotPassword=false;otpNote=''">Back to sign in</button></template></div><div v-else class="wrap admin-dashboard"><div class="admin-heading"><div><p class="eyebrow">RAWR admin</p><h1>Orders at a glance.</h1></div><button class="button dark" @click="logout">Log out</button></div><div v-if="analytics" class="metrics"><article><span>Total orders</span><b>{{analytics.totalOrders}}</b></article><article><span>Revenue</span><b>₹{{analytics.totalRevenue}}</b></article><article><span>Avg. cart value</span><b>₹{{analytics.averageCartValue}}</b></article><article><span>Open issues</span><b>{{openTickets}}</b></article></div><section class="admin-grid"><section><h2>Sales by location</h2><div class="location-list"><p v-if="!analytics?.salesByLocation?.length">No completed address data yet.</p><div v-for="place in analytics?.salesByLocation" :key="place.location"><span>{{place.location}}</span><b>{{place.orders}} order{{place.orders===1?'':'s'}}</b></div></div></section></section><section class="order-list"><h2>All orders</h2><article v-for="order in orders" :key="order.id"><div class="order-main"><div><b>Order #{{order.id}}</b><span>{{new Date(order.createdAt).toLocaleString()}}</span></div><div><b>{{order.customerName||'Customer name unavailable'}}</b><span>{{order.email}} · {{order.phone||'No phone'}}</span></div><div><span>{{order.address||'Address unavailable'}}</span></div><div><b>₹{{order.total||order.quantity*120+59}}</b><span>{{order.quantity}} bar{{order.quantity===1?'':'s'}}</span></div><select :value="currentStatus(order)" @change="changeStatus(order,$event.target.value)"><option value="pending">Pending</option><option value="complete">Complete</option></select></div><div v-if="order.tickets.length" class="tickets"><div v-for="ticket in order.tickets" :key="ticket.id"><span><b>Issue #{{ticket.id}}</b> — {{ticket.message}}</span><button v-if="ticket.status==='open'" @click="closeTicket(ticket)">Mark resolved</button><small v-else>Resolved</small></div></div></article><p v-if="!orders.length" class="note">No orders yet.</p></section></div></section></template>
